package com.hbm.machine.oilcatalyticcracker;
import com.hbm.api.machine.*;
import com.hbm.energy.NodeConnection;
import com.hbm.fluid.*;
import com.hbm.fluid.network.*;
import com.hbm.multiblock.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
/** Source steam-powered five-tank cracker: port FIFO, tank setup, two attempts every global5ticks,25block sync. */
public final class CatalyticCrackerEntity extends BlockEntity implements StandardFluidTransceiver,IFluidCopiable,MachineView,MuffledMachine {
 public final FluidTank[] tanks={new FluidTank(HbmFluids.fromName("BITUMEN"),4000),new FluidTank(HbmFluids.fromName("STEAM"),8000),new FluidTank(HbmFluids.fromName("OIL"),4000),new FluidTank(HbmFluids.fromName("PETROLEUM"),4000),new FluidTank(HbmFluids.fromName("SPENTSTEAM"),800)};
 private boolean muffled;public boolean tilted;private FluidPorts fluidPorts;private List<Port> connected=List.of();private CompoundTag lastSync;
 public CatalyticCrackerEntity(BlockPos pos,BlockState state){super(CatalyticCrackerContent.ENTITY.get(),pos,state);}@Override public boolean isValidBlockState(BlockState state){return getType().isValid(state)&&DummyableBlock.isCore(state);}
 public record Port(BlockPos position,Direction side){}
 public static List<Port> ports(BlockPos core,Direction dir){var rot=dir.getClockWise();var result=new ArrayList<Port>();int[][] points={{3,1,0},{3,-2,0},{-3,1,1},{-3,-2,1},{2,2,2},{2,-3,3},{-2,2,2},{-2,-3,3}};for(var point:points){var pos=core.relative(dir,point[0]).relative(rot,point[1]);var side=switch(point[2]){case 0->dir;case 1->dir.getOpposite();case 2->rot;default->rot.getOpposite();};result.add(new Port(pos,side));}return result;}
 public boolean portConnects(BlockPos pos,Direction side){return side!=null&&ports(worldPosition,DummyableBlock.facing(getBlockState())).stream().anyMatch(p->p.position.equals(pos)&&p.side==side);}
 private void updatePorts(ServerLevel server){var active=new ArrayList<Port>();for(var port:ports(worldPosition,DummyableBlock.facing(getBlockState())))if(server.hasChunkAt(port.position)&&server.getBlockState(port.position).is(getBlockState().getBlock())&&DummyableBlock.isPort(server.getBlockState(port.position)))active.add(port);if(!active.equals(connected)){disconnect();connected=List.copyOf(active);if(!active.isEmpty()){var positions=active.stream().map(Port::position).toArray(BlockPos[]::new);var connections=active.stream().map(p->new NodeConnection(p.position.relative(p.side),p.side)).toArray(NodeConnection[]::new);fluidPorts=new FluidPorts(positions,connections);}}if(fluidPorts!=null)fluidPorts.update(server,this);}
 public static void tick(Level level,BlockPos pos,BlockState state,CatalyticCrackerEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);}
 private void serverTick(ServerLevel server){updatePorts(server);var recipe=CatalyticCrackerRecipes.find(server.getRecipeManager(),tanks[0].getTankType());setupTanks(recipe);if(server.getGameTime()%5==0&&recipe!=null)crack(recipe);setChanged();var snapshot=getUpdateTag(server.registryAccess());if(!snapshot.equals(lastSync)||server.getGameTime()%20==0){lastSync=snapshot.copy();var packet=getUpdatePacket();for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<625)player.connection.send(packet);}}
 private void setupTanks(CatalyticCrackerRecipe recipe){if(recipe!=null){tanks[1].setTankType(HbmFluids.fromName("STEAM"));tanks[2].setTankType(recipe.outputFluids().get(0).type);tanks[3].setTankType(recipe.outputFluids().get(1).type);tanks[4].setTankType(HbmFluids.fromName("SPENTSTEAM"));}else for(int i=2;i<5;i++)tanks[i].setTankType(HbmFluids.NONE);}
 private void crack(CatalyticCrackerRecipe recipe){int left=recipe.outputFluids().get(0).fill,right=recipe.outputFluids().get(1).fill;for(int i=0;i<2;i++)if(tanks[0].getFill()>=100&&tanks[1].getFill()>=200&&tanks[2].getFill()+left<=tanks[2].getMaxFill()&&tanks[3].getFill()+right<=tanks[3].getMaxFill()&&tanks[4].getFill()+2<=tanks[4].getMaxFill()){tanks[0].setFill(tanks[0].getFill()-100);tanks[1].setFill(tanks[1].getFill()-200);tanks[2].setFill(tanks[2].getFill()+left);tanks[3].setFill(tanks[3].getFill()+right);tanks[4].setFill(tanks[4].getFill()+2);}}
 @Override public FluidTank[] getAllTanks(){return tanks;}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tanks[0],tanks[1]};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{tanks[2],tanks[3],tanks[4]};}@Override public FluidTank getTankToPaste(){return tanks[0];}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null&&side.getAxis().isHorizontal();}
 @Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rest=StandardFluidTransceiver.super.transferFluid(type,pressure,amount);if(rest!=amount)setChanged();return rest;}@Override public void useUpFluid(HbmFluidType type,int pressure,long amount){StandardFluidTransceiver.super.useUpFluid(type,pressure,amount);if(amount>0)setChanged();}
 @Override public long energyStored(){return 0;}@Override public long energyCapacity(){return 0;}@Override public List<TankView> tanks(){return Arrays.stream(tanks).map(t->new TankView(t.getTankType(),t.getFill(),t.getMaxFill())).toList();}@Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
 private void write(CompoundTag tag){for(int i=0;i<5;i++)tanks[i].writeToNBT(tag,"tank"+i);tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}private void read(CompoundTag tag){for(int i=0;i<5;i++)tanks[i].readFromNBT(tag,"tank"+i);muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);write(tag);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);read(tag);}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();write(tag);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){read(tag);}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 private void disconnect(){if(fluidPorts!=null&&level instanceof ServerLevel server)fluidPorts.remove(server);fluidPorts=null;connected=List.of();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
}
